import json,html,pathlib
r=pathlib.Path(__file__).parent
data=json.loads((r/'cards.json').read_text(encoding='utf-8'))
parts=[]
for c in data['cards']:
 esc=html.escape
 grid=''.join(f'<span class="tile tile-{v}" title="{data["coordinateConvention"]["legend"][v]}">{"●" if v=="O" else ""}</span>' for line in c['pattern5x5'] for v in line)
 parts.append(f'<article data-search="{esc((c["id"]+" "+c["nameEn"]+" "+c["abilityTextEn"]).lower())}"><a href="{esc(c["image"])}"><img src="{esc(c["image"])}" alt="{esc(c["nameEn"])}" loading="lazy" width="390" height="534"></a><div class="details"><small>{c["id"]} · #{c["originalNumber"]:03}</small><h2>{esc(c["nameEn"])}</h2><p><b>Power {c["power"]}</b> · Rank {c["rank"]}{" · Replacement" if c["rank"]==0 else ""}</p><div class="grid" role="img" aria-label="{esc(" / ".join(c["pattern5x5"]))}">{grid}</div><p>{esc(c["abilityTextEn"])}</p><details><summary>Coordenadas</summary><pre>Expansão: {esc(str(c["expansionOffsets"]))}\nEfeito: {esc(str(c["effectOffsets"]))}</pre></details></div></article>')
page='''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Referência das 145 cartas — Paradox</title><style>
*{box-sizing:border-box}body{margin:0;background:#10191e;color:#e4e9e5;font:15px/1.6 system-ui,sans-serif}header,main{max-width:1500px;margin:auto;padding:24px}h1{font:36px Georgia,serif;color:#e6ca92}header p{max-width:850px}a{color:#a5e7dc}input{padding:14px;width:min(100%,650px);background:#19282e;color:inherit;border:1px solid #8fa7a0;font:inherit}#count{margin-left:15px}.catalog{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:24px}article{background:#19262b;border:1px solid #7d7255;overflow:hidden}article[hidden]{display:none}article img{display:block;width:100%;height:auto}.details{padding:18px}h2{font:24px Georgia,serif;margin:7px 0}.grid{display:grid;grid-template-columns:repeat(5,15px);gap:3px;margin:14px 0}.tile{height:15px;background:#504637;border:2px solid transparent}.tile-O{background:#fff;color:#18282d;line-height:10px;text-align:center}.tile-R,.tile-B{background:#f2b65b}.tile-E,.tile-B{border-color:#ee6947}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px}.legend span{display:inline-block;margin-right:18px}small{color:#b5c2bd}
</style><header><h1>Referência das 145 cartas</h1><p>Captura de <a href="https://www.queensbloodonline.com/decks/">Queen’s Blood Online</a> em 21/10/2026. Nomes e imagens originais para referência. Esta captura de um site não oficial ainda não comprova equivalência completa com FFVII Rebirth.</p><p>Uma carta ocupa somente a casa de origem. O desenho indica expansão territorial e casas afetadas pela habilidade. Coordenadas [linha, coluna], origem [0, 0], linha positiva para baixo e coluna positiva para a direita. Espelhe as colunas para o jogador do lado oposto.</p><p class="legend"><span>Branco: origem</span><span>Dourado: expansão</span><span>Borda vermelha: efeito</span><span>Dourado + borda: ambos</span></p><p>Rank 0 significa substituição de uma carta aliada. Cartas auxiliares geradas por habilidades ainda não estão incluídas.</p><label for="search">Buscar nome, ID ou habilidade</label><br><input id="search" type="search" placeholder="Ex.: qb-013, Crystalline Crab, destroy"><output id="count">145 cartas</output></header><main class="catalog">'''+''.join(parts)+'''</main><script>document.querySelector('#search').addEventListener('input',event=>{const q=event.target.value.toLowerCase().trim();let count=0;document.querySelectorAll('article').forEach(card=>{card.hidden=!card.dataset.search.includes(q);if(!card.hidden)count++;});document.querySelector('#count').textContent=count+' cartas';});</script></html>'''
(r/'catalog.html').write_text(page,encoding='utf-8')
print('Generated offline gallery with',len(parts),'cards')
